import React, { useState } from 'react';
import axios from 'axios';
import { Card, CardContent, CardActions, Typography, Button, TextField, IconButton } from '@mui/material';
import ThumbUpIcon from '@mui/icons-material/ThumbUp';
import CommentIcon from '@mui/icons-material/Comment';

const Blog = ({ blog, fetchBlogs }) => {
    const [comment, setComment] = useState('');

    const handleCommentSubmit = async (e) => {
        e.preventDefault();
        await axios.post(`http://localhost:8080/api/blogs/${blog.id}/comments`, comment);
        fetchBlogs();
        setComment('');
    };

    const handleLike = async () => {
        await axios.post(`http://localhost:8080/api/blogs/${blog.id}/like`);
        fetchBlogs();
    };

    return (
        <Card sx={{ mb: 2 }}>
            <CardContent>
                <Typography variant="h5" gutterBottom>{blog.title}</Typography>
                <Typography variant="body2" color="text.secondary" paragraph>{blog.content}</Typography>
                <Typography variant="subtitle1">Author: {blog.author}</Typography>
                <Typography variant="subtitle1">Category: {blog.category}</Typography>
                <Typography variant="subtitle1">Likes: {blog.likes}</Typography>
            </CardContent>
            <CardActions>
                <IconButton onClick={handleLike} color="primary">
                    <ThumbUpIcon />
                </IconButton>
                <Typography variant="body2">{blog.likes}</Typography>
            </CardActions>
            <CardContent>
                <Typography variant="h6">Comments</Typography>
                <ul>
                    {blog.comments.map((c, index) => (
                        <li key={index}>{c}</li>
                    ))}
                </ul>
                <form onSubmit={handleCommentSubmit}>
                    <TextField
                        label="Add a comment"
                        variant="outlined"
                        fullWidth
                        value={comment}
                        onChange={(e) => setComment(e.target.value)}
                        required
                    />
                    <Button variant="contained" color="primary" type="submit" startIcon={<CommentIcon />}>
                        Comment
                    </Button>
                </form>
            </CardContent>
        </Card>
    );
};

export default Blog;
